// Independent upstream NanoVDB accessor reference, not a runtime Host.
#include <nanovdb/tools/CreatePrimitives.h>
#include <nanovdb/tools/CreateNanoGrid.h>
#include <nanovdb/tools/GridValidator.h>
#include <fstream>
#include <iostream>
#include <vector>
#include <string>
#include <cmath>
#include <stdexcept>
static uint32_t hash(uint32_t lo,uint32_t hi){uint32_t h=lo^(hi*0x9e3779b9u);h^=h>>16;h*=0x7feb352du;h^=h>>15;h*=0x846ca68bu;return h^(h>>16);}
template<class H>void write(H&handle,const std::string&dir,const std::string&name,const std::vector<nanovdb::Coord>&points){
 auto*g=handle.template grid<float>();if(!g||!nanovdb::tools::isValid(g,nanovdb::CheckMode::Full))throw std::runtime_error("Upstream full grid validation failed");std::ofstream raw(dir+"/"+name+".raw",std::ios::binary);raw.write((const char*)handle.data(),handle.size());raw.close();auto a=g->getAccessor();std::ofstream indices(dir+"/"+name+"-coordinates.i32",std::ios::binary),world(dir+"/"+name+"-world.f32",std::ios::binary),values(dir+"/"+name+"-values.f32",std::ios::binary),active(dir+"/"+name+"-active.u32",std::ios::binary),worldValues(dir+"/"+name+"-world-values.f32",std::ios::binary),worldActive(dir+"/"+name+"-world-active.u32",std::ios::binary);for(const auto&p:points){int32_t xyz[]={p[0],p[1],p[2]};const auto w=g->map().applyMapF(nanovdb::Vec3f(float(p[0]),float(p[1]),float(p[2])));float wc[]={w[0],w[1],w[2]},value=a.getValue(p);uint32_t on=a.isActive(p)?1:0;indices.write((const char*)xyz,12);world.write((const char*)wc,12);values.write((const char*)&value,4);active.write((const char*)&on,4);const auto back=g->map().applyInverseMapF(w);nanovdb::Coord nearest(int32_t(std::floor(back[0]+.5f)),int32_t(std::floor(back[1]+.5f)),int32_t(std::floor(back[2]+.5f)));const float wv=a.getValue(nearest);const uint32_t wa=a.isActive(nearest)?1:0;worldValues.write((const char*)&wv,4);worldActive.write((const char*)&wa,4);}std::cout<<"{\"case\":\""<<name<<"\",\"gridBytes\":"<<handle.size()<<",\"samples\":"<<points.size()<<",\"activeVoxels\":"<<g->activeVoxelCount()<<",\"fullUpstreamValidation\":true}"<<std::endl;
}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("Explicit output directory required");std::string dir=argv[1];std::vector<nanovdb::Coord>sphere;for(int z=-10;z<=10;z++)for(int y=-10;y<=10;y++)for(int x=-10;x<=10;x++)sphere.emplace_back(x,y,z);auto h=nanovdb::tools::createLevelSetSphere<float>(5.,nanovdb::Vec3d(0),1.,3.,nanovdb::Vec3d(0),"reference-sdf",nanovdb::tools::StatsMode::All,nanovdb::CheckMode::Full);write(h,dir,"sdf",sphere);
 nanovdb::tools::build::Grid<float>grid(0.,"reference-fog",nanovdb::GridClass::FogVolume);auto&root=grid.tree().root();grid.tree().setValue(nanovdb::Coord(0),1.25f);root.template addTile<1>(nanovdb::Coord(8,0,0),.25f,false);root.template addTile<2>(nanovdb::Coord(128,0,0),.5f,true);root.template addTile<3>(nanovdb::Coord(4096,0,0),.75f,true);root.template addTile<3>(nanovdb::Coord(-8192,0,0),-2.f,false);std::vector<nanovdb::Coord>points;for(auto v:{-8193,-8192,-5000,-4097,-4096,-1,0,1,7,8,15,127,128,255,4095,4096,8191,8192}){points.emplace_back(v,0,0);points.emplace_back(v,1,2);}
 int collisions=0;for(int32_t i=3;collisions<16&&i<524287;i++){if((hash(0,uint32_t(i)<<10)&255u)==0){auto c=nanovdb::Coord(i*4096,0,0);root.template addTile<3>(c,4.f+float(collisions),collisions%2==0);points.push_back(c);points.emplace_back(c[0]+4095,1,2);collisions++;}}if(collisions!=16)throw std::runtime_error("Collision fixture not constructed");double mat[3][3]={{-.5,.25,0},{0,.5,0},{0,0,2}},inv[3][3]={{-2,1,0},{0,2,0},{0,0,.5}};grid.mMap.set(mat,inv,nanovdb::Vec3d(1.25,-2.5,4.75));auto fog=nanovdb::tools::createNanoGrid(grid,nanovdb::tools::StatsMode::All,nanovdb::CheckMode::Full);write(fog,dir,"fog",points);return 0;}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
